import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ClienteList = () => {
  const [clientes, setClientes] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    // Requisição para o backend, usando URL relativa
    axios.get('/clientes')
      .then(response => {
        setClientes(response.data); // Armazena os dados dos clientes no estado
      })
      .catch(error => {
        setError('Erro ao carregar a lista de clientes');
        console.error(error);
      });
  }, []); // O array vazio significa que a requisição será feita apenas uma vez, ao montar o componente.

  return (
    <div>
      <h1>Lista de Clientes</h1>
      {error && <p>{error}</p>}
      <ul>
        {clientes.map(cliente => (
          <li key={cliente.id}>
            {cliente.nome} - {cliente.email} - {cliente.telefone}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default ClienteList;
